INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(2301, 'Exodus 29:39', 'Exodus', 29, 39, '&nbsp;يو ګډُورے د سحر په وخت کښې د قربانۍ په توګه پېش کوه او بل په ماښام کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2302, 'Exodus 29:40', 'Exodus', 29, 40, '&nbsp;د وړومبى ګډُورى سره يو کلو د غنمو ښۀ اوړۀ پېش کړه چې د زيتُونو يو ليټر سوچه تېل ورسره ګډ وى. او يو ليټر مے د نذرانې په توګه پېش کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2303, 'Exodus 29:41', 'Exodus', 29, 41, '&nbsp;دوېم ګډُورے په ماښام کښې قربانى کړه او د سحر په شان هم هغه هومره اوړو سره، د زيتُونو تېلو او مے سره يې پېش کړه. دا مالِک خُدائ ته په اور سوزېدونکې نذرانه ده او د دې خوشبو په هغۀ ښۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2304, 'Exodus 29:42', 'Exodus', 29, 42, '&nbsp;په راتلونکى ټولو وختونو کښې، دا سوزېدونکې نذرانه زما د حضور خېمې د دروازې په خولۀ کښې به پېش کولے شى. چې هلته به تاسو د مالِک خُدائ سره ملاقات وکړئ او تا سره به خبرې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2305, 'Exodus 29:43', 'Exodus', 29, 43, '&nbsp;هلته به بنى اِسرائيل زما سره ملاقات وکړى او زما د حضور جلال به هغه ځائ مقدس کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2306, 'Exodus 29:44', 'Exodus', 29, 44, '&nbsp;زۀ به خېمه او قربان‌ګاه مقدس کړم او زۀ به هارون او د هغۀ زامن رابېل کړم چې د اِمامانو په توګه زما خِدمت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2307, 'Exodus 29:45', 'Exodus', 29, 45, '&nbsp;زۀ به د بنى اِسرائيلو په مينځ کښې اوسېږم او زۀ به د هغوئ خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2308, 'Exodus 29:46', 'Exodus', 29, 46, '&nbsp;هغوئ ته به پته ولګى چې زۀ مالِک خُدائ د هغوئ خُدائ پاک يم چا چې هغوئ د مِصر د مُلک نه راوويستل چې زۀ د هغوئ په مينځ کښې اوسېږم. زۀ مالِک خُدائ د هغوئ خُدائ پاک يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2309, 'Exodus 30:1', 'Exodus', 30, 1, '&nbsp;د خوشبويۍ سوزولو دپاره، د کيکر د لرګى نه يوه قربان‌ګاه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2310, 'Exodus 30:2', 'Exodus', 30, 2, '&nbsp;دا به څلور‌ګوټه وى، چې اتلس اِنچۍ اوږده، اتلس اِنچۍ پلنه او يو ګز اوچته وى. د ښکرو په شان څلور ګوټونه ورله جوړ کړه چې ورسره يو ځائ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2311, 'Exodus 30:3', 'Exodus', 30, 3, '&nbsp;د هغې په چت، څلورو واړو طرفونو او د هغې د ښکرونو په شان څيزونو باندې د سوچه سرو زرو پترى وخېژوه او ګېرچاپېره ترې نه د سرو زرو غاړه شان تاو کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2312, 'Exodus 30:4', 'Exodus', 30, 4, '&nbsp;د وړلو دپاره دوه د سرو زرو ګول کَړۍ ورله جوړې کړه او لاندې يې دواړو طرفونو ته د غاړې سره وتړه چې هغه بازوګان ونيسى چې د کومو په ذريعه دا وړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2313, 'Exodus 30:5', 'Exodus', 30, 5, '&nbsp;بازوګان د کيکر د لرګى نه جوړ کړه او په دې باندې د سرو زرو پترى وخېژوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2314, 'Exodus 30:6', 'Exodus', 30, 6, '&nbsp;دا قربان‌ګاه د هغې پړدې نه بهر کېږده کومه چې د لوظ صندوق مخې ته ځوړنده ده. دا هغه ځائ دے چې چرته به زۀ تا سره ملاقات کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2315, 'Exodus 30:7', 'Exodus', 30, 7, '&nbsp;هر سحر وختى چې هارون کله د ډيوو تيارولو له راځى، هغه به په دې باندې خوشبويۍ سوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2316, 'Exodus 30:8', 'Exodus', 30, 8, '&nbsp;چې کله هغه په ماښام کښې ډيوې بلوى نو هم دغه شان به کوى. دا د خوشبويۍ نذرانه به په راتلونکى ټولو وختونو کښې جارى ساتلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2317, 'Exodus 30:9', 'Exodus', 30, 9, '&nbsp;په دې قربان‌ګاه باندې حرامه خوشبوئى مۀ پېش کوئ او د يو ځناور نذرانه، يا د غلې نذرانه مۀ پېش کوئ او يا د څښلو څۀ نذرانه هم په دې مۀ تويَوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2318, 'Exodus 30:10', 'Exodus', 30, 10, '&nbsp;په کال کښې يو ځل به هارون د قربان‌ګاه د کفارې رسم ادا کوى، چې کله د ګناه دپاره د قربان شوى ځناور وينه د قربان‌ګاه د ښکرو په شان څيزونو باندې تويَولے شى نو دا پاکيږى. په راتلونکى ټولو وختونو کښې به دا د کفارې رسم هر کال ادا کيږى. دا قربان‌ګاه به پوره مقدسه وى، ځکه چې دا ما مالِک خُدائ ته وقف ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2319, 'Exodus 30:11', 'Exodus', 30, 11, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2320, 'Exodus 30:12', 'Exodus', 30, 12, '&nbsp;”کله چې تۀ د بنى اِسرائيلو مردم‌شمارى کوې، نو هر يو سړے به ما له د خپل ژوند قيمت راکوى، چې کله مردم‌شمارى کيږى، نو هيڅ بلا به ورباندې نۀ راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2321, 'Exodus 30:13', 'Exodus', 30, 13, '&nbsp;هر يو کس چې په دې مردم‌شمارۍ کښې شامليږى نو هغه به خامخا د منلے شوى معيار په مطابق هغه مقرر شوے قيمت ورکوى. هر يو کس به دا مالِک خُدائ ته د نذرانې په توګه ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2322, 'Exodus 30:14', 'Exodus', 30, 14, '&nbsp;هر يو کس به په دې مردم‌شمارۍ کښې شمېرلے شى، د هر يو کس عُمر چې شل کاله يا د شلو کالو نه زيات وى، نو هغه به دا قيمت ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2323, 'Exodus 30:15', 'Exodus', 30, 15, '&nbsp;چې کله هغوئ مالِک خُدائ ته د خپل ژوند قيمت ادا کوى نو مالدار او غريب به يو برابر ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2324, 'Exodus 30:16', 'Exodus', 30, 16, '&nbsp;د بنى اِسرائيلو نه د کفارې دا پېسې راټولوه او زما د حضور په خېمه يې خرچ کوه. دا محصُول به د هغوئ د ژوند قيمت وى او زۀ، مالِک خُدائ به هغوئ ياد ساتم او د هغوئ حِفاظت به کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2325, 'Exodus 30:17', 'Exodus', 30, 17, '&nbsp;او مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2326, 'Exodus 30:18', 'Exodus', 30, 18, '&nbsp;”د وينځلو دپاره د زېړو يو ښانک جوړ کړه چې بېخ يې هم د زېړو وى. دا د خېمې او د قربان‌ګاه په مينځ کښې کېږده او په هغې کښې اوبۀ واچوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2327, 'Exodus 30:19', 'Exodus', 30, 19, '&nbsp;هارون او د هغۀ زامن به په دې اوبو خپل لاسونه او پښې وينځى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2328, 'Exodus 30:20', 'Exodus', 30, 20, '&nbsp;د هغې نه مخکښې چې هغوئ خېمې ته ننوځى يا چې قربان‌ګاه ته د خوراک نذرانه پېش کولو دپاره نزدې کيږى. نو هغوئ به نۀ مړۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2329, 'Exodus 30:21', 'Exodus', 30, 21, '&nbsp;هغوئ دې خامخا خپل لاسونه او پښې وينځى، چې مړۀ نۀ شى. دا يو قانون دے چې هغوئ او د هغوئ اولاد به همېشه دپاره په دې عمل کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2330, 'Exodus 30:22', 'Exodus', 30, 22, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2331, 'Exodus 30:23', 'Exodus', 30, 23, '&nbsp;”دا ښې مصالحې واخله، شپږ کلو اوبۀ شوې خوشبوداره مُر، درې کلو خوشبوداره دارچينى، درې کلو خوشبودار لرګے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2332, 'Exodus 30:24', 'Exodus', 30, 24, '&nbsp;او شپږ کلو د سناد د پاڼو مصالحه، دا ټول به د منلے شوى معيار په مطابق تَللے شوى وى. څلور ليټره د زيتُونو تېل هم ورسره مِلاو کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2333, 'Exodus 30:25', 'Exodus', 30, 25, '&nbsp;او د غوړولو مقدس تېل ترې نه جوړ کړه، داسې يې مِلاو کړه لکه چې د عطرو والا دا کار کړے وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2334, 'Exodus 30:26', 'Exodus', 30, 26, '&nbsp;په دې باندې دا څيزونه غوړ کړه، زما د حضور خېمه، د لوظ صندوق،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2335, 'Exodus 30:27', 'Exodus', 30, 27, '&nbsp;مېز او د هغې ټول سامان، ډيوټ او د هغې سامان، د خوشبويۍ سوزولو قربان‌ګاه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2336, 'Exodus 30:28', 'Exodus', 30, 28, '&nbsp;د سوزېدونکې نذرانې قربان‌ګاه، ورسره د هغې ټول سامان، او د وينځلو ښانک او د دې بېخ هم په تېلو غوړ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2337, 'Exodus 30:29', 'Exodus', 30, 29, '&nbsp;په دې طريقه دا څيزونه وقف کړه او دا به بېخى مقدس شى او هر څوک يا هر څيز چې د دې سره ولګى نو هغه به هم مقدس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2338, 'Exodus 30:30', 'Exodus', 30, 30, '&nbsp;بيا د هارون او د هغۀ د زامنو سرونه په تېلو غوړ کړه او زما په خِدمت کښې يې د اِمامانو په توګه مقرر کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2339, 'Exodus 30:31', 'Exodus', 30, 31, '&nbsp;بنى اِسرائيلو ته ووايه چې دا مقدس تېل به په راتلونکى ټولو وختونو کښې زما په خِدمت کښې استعماليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2340, 'Exodus 30:32', 'Exodus', 30, 32, '&nbsp;دا به د يو عام سړى په بدن باندې نۀ شى تويَولے او تاسو به د دې په شان خوشبويۍ نۀ جوړَوئ. دا مقدس دى او تاسو به خامخا دا مقدس ګڼئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2341, 'Exodus 30:33', 'Exodus', 30, 33, '&nbsp;کۀ هر څوک د دې په شان خوشبوئى جوړه کړى يا يې څوک د يو اِمام نه بغېر په بل چا پورې ولګوى نو هغه به نور زما د خلقو نه نۀ شى ګڼلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2342, 'Exodus 30:34', 'Exodus', 30, 34, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”د دې خوشبودارو مصالحو يوه يوه برابره حِصه واخله، مُر، صدف، کنډ او سوچه لوبان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2343, 'Exodus 30:35', 'Exodus', 30, 35, '&nbsp;د دې نه عطر جوړ کړه، دا داسې مِلاو کړه لکه چې يو د عطرو والا دا کار کړے وى. مالګه په کښې مِلاو کړه چې سوچه او مقدس وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2344, 'Exodus 30:36', 'Exodus', 30, 36, '&nbsp;او د دې څۀ حِصه مېده مېده کړه، دا زما د حضور خېمې ته يوسه او دا د لوظ صندوق مخې ته کېږده، هلته به زۀ تا سره ملاقات وکړم. دا پوره مقدس وګڼئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2345, 'Exodus 30:37', 'Exodus', 30, 37, '&nbsp;د خپلو ځانونو دپاره داسې خوشبوئى مۀ جوړَوئ چې دا څيزونه په کښې په دې طريقه استعمال شوى وى. دا يو مقدس څيز او دا مالِک خُدائ ته وقف وګڼئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2346, 'Exodus 30:38', 'Exodus', 30, 38, '&nbsp;کۀ څوک داسې يو څيز هم جوړ کړى او د عطرو په توګه يې استعمال کړى نو هغه به نور زما د خلقو نه نۀ شى ګڼلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2347, 'Exodus 31:1', 'Exodus', 31, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2348, 'Exodus 31:2', 'Exodus', 31, 2, '&nbsp;”ګوره، ما د يهوداه قبيلې، بضلى‌اېل غوره کړے دے، چې د اورى زوئ او د حُور نمسے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2349, 'Exodus 31:3', 'Exodus', 31, 3, '&nbsp;او ما هغه د خپل روح نه ډک کړے دے. ما هغۀ له پوهه، هُنر او د هر قِسم هُنر په کار کښې قابليت ورکړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2350, 'Exodus 31:4', 'Exodus', 31, 4, '&nbsp;د سرو زرو، سپينو زرو او د زېړو ښائسته کار کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2351, 'Exodus 31:5', 'Exodus', 31, 5, '&nbsp;قيمتى کاڼى پرې کولو او تيارولو، د لرګى کار کولو، او د هر قِسم د هُنر کار دپاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2352, 'Exodus 31:6', 'Exodus', 31, 6, '&nbsp;او ګوره، ما اهلياب هم خوښ کړے دے چې د اخيسمک زوئ دے او د دان د قبيلې نه دے، چې هغوئ يو ځائ کار وکړى. ما نورو ټولو هُنرمندو له هم لوئ قابليت ورکړے دے، چې هغوئ هغه څۀ جوړ کړى چې ما حُکم ورکړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2353, 'Exodus 31:7', 'Exodus', 31, 7, '&nbsp;يعنې زما د حضور خېمه، د لوظ صندوق او د کفارې تخت چې ورباندې پروت دے، د خېمې نور ټول سامان،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2354, 'Exodus 31:8', 'Exodus', 31, 8, '&nbsp;مېز او د هغې سامان، د سوچه سرو زرو ډيوټ او د هغې ټول سامان، د خوشبويۍ د سوزولو قربان‌ګاه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2355, 'Exodus 31:9', 'Exodus', 31, 9, '&nbsp;د سوزېدونکې نذرانې قربان‌ګاه او د هغې ټول سامان، د وينځلو ښانک او د هغې بېخ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2356, 'Exodus 31:10', 'Exodus', 31, 10, '&nbsp;د هارون او د هغۀ د زامنو دپاره د اِمامانو ښائسته لِباس چې کله هغوئ د اِمامانو په توګه خِدمت کوى نو دا دې استعمالوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2357, 'Exodus 31:11', 'Exodus', 31, 11, '&nbsp;د غوړولو تېل او د مقدس ځائ دپاره خوشبويۍ. دا څيزونه دې هم هغه شان جوړ کړى چې څنګه ما تا ته حُکم کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2358, 'Exodus 31:12', 'Exodus', 31, 12, '&nbsp;بيا مالِک خُدائ موسىٰ له حُکم ورکړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2359, 'Exodus 31:13', 'Exodus', 31, 13, '&nbsp;چې، ”بنى اِسرائيلو ته ووايه، تاسو د سبت، يعنې د آرام کولو ورځ منئ، دا به په راتلونکى ټولو وختونو کښې زما او ستاسو په مينځ کښې يوه نښه وى، چې تاسو ته پته ولګى چې ما مالِک خُدائ تاسو خپل خلق جوړ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2360, 'Exodus 31:14', 'Exodus', 31, 14, '&nbsp;تاسو خامخا د سبت ورځ منئ، ځکه چې دا ستاسو دپاره مقدسه ده. چې څوک هم دا نۀ منى او په هغه ورځ کار کوى، نو هغه دې ووژلے شى. او څوک چې په هغه ورځ باندې کار کوى نو هغه به د بنى اِسرائيلو نه نۀ شى ګڼلے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2361, 'Exodus 31:15', 'Exodus', 31, 15, '&nbsp;ستاسو سره د خپل کار کولو دپاره شپږ ورځې شته، خو اوومه ورځ د سبت يعنې د آرام ورځ ده، هغه ما مالِک خُدائ ته وقف شوې ده. هر څوک چې څۀ قِسم کار هم په هغه ورځ وکړى نو هغه دې ووژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2362, 'Exodus 31:16', 'Exodus', 31, 16, '&nbsp;بنى اِسرائيل دې دا ورځ د لوظ د يوې نښې په توګه همېشه دپاره منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2363, 'Exodus 31:17', 'Exodus', 31, 17, '&nbsp;دا به همېشه دپاره زما او د بنى اِسرائيلو په مينځ کښې يوه نښه وى، ځکه چې ما مالِک خُدائ په شپږ ورځو کښې آسمان او زمکه جوړ کړل او په اوومه ورځ ما کار بس کړو او څۀ مې ونۀ کړل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2364, 'Exodus 31:18', 'Exodus', 31, 18, '&nbsp;چې کله خُدائ پاک د سينا په غرۀ باندې د موسىٰ سره خبرې خلاصې کړې، نو هغۀ له يې هغه د کاڼى دوه تختې ورکړې چې په کومو باندې خُدائ پاک په خپله حُکمونه ليکلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2365, 'Exodus 32:1', 'Exodus', 32, 1, '&nbsp;چې کله خلقو وليدل چې موسىٰ د غرۀ نه راکوز نۀ شو او ډېر وخت يې هلته تېر کړو، نو هغوئ په هارون راغونډ شول او هغۀ ته يې ووئيل، ”مونږ نۀ پوهيږو چې په دې سړى، موسىٰ څۀ وشول، چې مونږ يې د مِصر نه راوويستلو، مونږ له معبودان جوړ کړه چې مونږ ته لارښودنه کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2366, 'Exodus 32:2', 'Exodus', 32, 2, '&nbsp;هارون هغوئ ته ووئيل، ”د خپلو ښځو، زامنو او د خپلو لوڼو نه د سرو زرو والۍ راوباسئ او ما له يې راوړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2367, 'Exodus 32:3', 'Exodus', 32, 3, '&nbsp;نو ټولو خلقو خپلې د سرو زرو والۍ راوويستلې او هارون له يې راوړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2368, 'Exodus 32:4', 'Exodus', 32, 4, '&nbsp;هغۀ د هغوئ والۍ واخستلې، ويلې يې کړې او د سخى په شکل يې يو بُت ترې نه جوړ کړو. هغوئ ووئيل، ”اے بنى اِسرائيلو، دا زمونږ خُدائ دے چې مونږ يې د مِصر د مُلک نه راوويستلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2369, 'Exodus 32:5', 'Exodus', 32, 5, '&nbsp;بيا هارون د سرو زرو سخى په مخکښې يوه قربان‌ګاه جوړه کړه او اِعلان يې وکړو، ”سبا به د مالِک خُدائ دپاره اختر وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2370, 'Exodus 32:6', 'Exodus', 32, 6, '&nbsp;بل سحر وختى هغوئ څۀ ځناور راوستل چې د سوزېدونکې نذرانې په توګه يې قربان کړى او چې نور د خوړلو د سلامتۍ نذرانې په توګه پېش کړى. هغه خلق د خوړلو او څښلو دپاره کښېناستل او بيا هغوئ پاڅېدل، د مستۍ او عياشۍ سره ګډېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2371, 'Exodus 32:7', 'Exodus', 32, 7, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”سمدستى واپس لاندې کوز شه، ځکه چې ستا هغه خلق د ګناه په وجه خراب شوى دى، چې تا د مِصر نه راويستلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2372, 'Exodus 32:8', 'Exodus', 32, 8, '&nbsp;چې په کومه لاره ما هغوئ له د عمل کولو حُکم ورکړے وو هغوئ زر د هغې نه بې‌لارې شوى دى، هغوئ د ويلې شوى سرو زرو نه سخے جوړ کړے دے، د هغۀ عبادت يې کړے دے او قربانۍ يې ورته پېش کړى دى. هغوئ وائى چې هغه يې خُدائ دے چا چې د مِصر د مُلک نه راويستلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2373, 'Exodus 32:9', 'Exodus', 32, 9, '&nbsp;ما ته پته ده چې هغوئ څومره ضدى خلق دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2374, 'Exodus 32:10', 'Exodus', 32, 10, '&nbsp;اوس، تۀ ما مۀ منعې کوه. زۀ هغوئ ته په قهر يم او هغوئ تباه کوم. بيا به زۀ تا او ستا د اولاد نه يو لوئ قوم جوړ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2375, 'Exodus 32:11', 'Exodus', 32, 11, '&nbsp;خو موسىٰ مالِک خُدائ خپل خُدائ پاک ته سوال کولو او ورته يې وفرمائيل، ”مالِکه خُدايه، تۀ ولې خپلو خلقو ته دومره په قهر يې، چې هغوئ دې د خپل لوئ طاقت او خپل لوئ قُدرت سره د مِصر د مُلک نه راوويستل؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2376, 'Exodus 32:12', 'Exodus', 32, 12, '&nbsp;مِصريانو ته دې د پېغور کولو موقع مِلاو شى څۀ چې ووائى چې تا خپل خلق د مِصر نه د دې دپاره راوويستل چې په غرونو کښې يې ووژنې او هغوئ بېخى تباه کړې؟ خپل قهر بس کړه، خپله فېصله بدله کړه او په خپلو خلقو دا تباهى مۀ راوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2377, 'Exodus 32:13', 'Exodus', 32, 13, '&nbsp;خپل خِدمت کوونکى اِبراهيم، اِسحاق او يعقوب راياد کړه، تا چې د هغوئ سره کوم پوخ لوظ کړے دے هغه راياد کړه چې هغوئ له به دومره ډېر اولاد ورکړې چې په آسمان کښې څومره ستورى دى او چې د هغوئ اولاد له به هغه ټول مُلک ورکوې چې تا يې وعده کړې ده چې هغه به همېشه دپاره د هغوئ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2378, 'Exodus 32:14', 'Exodus', 32, 14, '&nbsp;نو مالِک خُدائ خپله فېصله بدله کړه او په خپلو خلقو يې هغه تباهى رانۀ وستله د کومې په حقله وى چې هغۀ فرمائيلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2379, 'Exodus 32:15', 'Exodus', 32, 15, '&nbsp;موسىٰ واپس د غرۀ نه راکوز شو، د ځان سره يې هغه د کاڼو دواړه تختې راوړې چې په دواړو مخونو يې حُکمونه ليکلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2380, 'Exodus 32:16', 'Exodus', 32, 16, '&nbsp;خُدائ پاک په خپله هغه تختې تيارې کړې وې او حُکمونه يې ورباندې ليکلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2381, 'Exodus 32:17', 'Exodus', 32, 17, '&nbsp;چې خلقو چغې وهلې نو يشوَع د خلقو شور واورېدو او موسىٰ ته يې وفرمائيل، ”په خېمو کښې د جګړې شور دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2382, 'Exodus 32:18', 'Exodus', 32, 18, '&nbsp;موسىٰ وفرمائيل، ”دا نۀ د فتحې او نۀ د شکست آواز معلوميږى، زۀ چې څۀ اورم دا د هغوئ د سندرو آواز دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2383, 'Exodus 32:19', 'Exodus', 32, 19, '&nbsp;چې کله موسىٰ خېمو ته ښۀ رانزدې شو او هغه سخے او د خلقو ګډېدل يې وليدل، نو سخت په قهر شو. هغۀ چې کومې تختې روانې کړې وې هغه يې هلته د غرۀ په لمن کښې وغورزولې او ماتې يې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2384, 'Exodus 32:20', 'Exodus', 32, 20, '&nbsp;هغوئ چې کوم سخے جوړ کړے وو هغه يې راواخستلو، په اور يې ويلې کړو او د اوړو په شان يې مېده مېده کړو او په اوبو کښې يې واچولو. بيا هغۀ دا په بنى اِسرائيلو باندې وڅښلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2385, 'Exodus 32:21', 'Exodus', 32, 21, '&nbsp;هغۀ هارون ته وفرمائيل، ”دې خلقو درباندې څۀ کړى دى، چې په دومره سخته ګناه دې آخته کړى دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2386, 'Exodus 32:22', 'Exodus', 32, 22, '&nbsp;هارون ورته وفرمائيل، ”زما نېکه، ما ته مۀ په قهر کېږه، تا ته پته ده چې دا خلق څومره بد‌کاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2387, 'Exodus 32:23', 'Exodus', 32, 23, '&nbsp;هغوئ ما ته ووئيل چې مونږ ته پته نشته چې په دې سړى، موسىٰ باندې څۀ شوى دى، چې مونږ يې د مِصر مُلک نه راوويستلو، راځئ، چې معبودان جوړ کړُو چې مونږ ته لارښودنه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2388, 'Exodus 32:24', 'Exodus', 32, 24, '&nbsp;ما هغوئ ته ووئيل چې ما له خپل د سرو زرو کالى راوړئ او چې د چا سره وُو نو هغه يې راوويستل او ما له يې راکړل. ما هغه کالى په اور کښې واچول او دا سخے ترې نه پخپله جوړ شو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2389, 'Exodus 32:25', 'Exodus', 32, 25, '&nbsp;موسىٰ وليدل چې هارون هغه خلق خپلې خوښې ته پرېښى وُو او د قابو نه يې وتلى وُو او د خپلو دشمنانو په مخکښې يې خپل ځانونه شرمولى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2390, 'Exodus 32:26', 'Exodus', 32, 26, '&nbsp;موسىٰ د خېمو ځائ د دروازې په خولۀ کښې ودرېدلو او آواز يې وکړو، ”هر څوک چې د مالِک خُدائ سره وى، ما له دې راشى.“ نو ټول ليويان هغۀ ته راغونډ شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2391, 'Exodus 32:27', 'Exodus', 32, 27, '&nbsp;نو هغۀ ورته وفرمائيل، ”مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک تاسو هر يو کس ته دا حُکم کوى چې خپله تُوره راوباسئ او د خېمو د يو سر نه تر بل سره پورې ځئ او هر يو کس دې خپل وروڼه، خپل دوستان او خپل ګاونډيان ووژنئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2392, 'Exodus 32:28', 'Exodus', 32, 28, '&nbsp;ليويانو د موسىٰ خبره ومنله او تقريباً درې زره کسان يې په هغه ورځ ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2393, 'Exodus 32:29', 'Exodus', 32, 29, '&nbsp;موسىٰ ليويانو ته ووئيل، ”نن تاسو خپل ځانونه د مالِک خُدائ په خِدمت کښې د اِمامانو په توګه وقف کړى دى، چې تاسو خپل زامن او وروڼه ووژل، نو مالِک خُدائ تاسو له خپل برکت درکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2394, 'Exodus 32:30', 'Exodus', 32, 30, '&nbsp;په ورپسې ورځ موسىٰ خلقو ته وفرمائيل، ”تاسو يوه لويه ګناه کړې ده. خو زۀ به يو ځل بيا مالِک خُدائ له غرۀ ته وخېژم، کېدے شى چې زۀ ستاسو د ګناه کفاره ادا کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2395, 'Exodus 32:31', 'Exodus', 32, 31, '&nbsp;نو موسىٰ واپس مالِک خُدائ ته ورَغلو او وې فرمائيل، ”افسوس، دې خلقو يوه لويه ګناه کړې ده. هغوئ د سرو زرو نه خُدائ جوړ کړے دے او د هغۀ عبادت يې کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2396, 'Exodus 32:32', 'Exodus', 32, 32, '&nbsp;اوس زۀ تا ته سوال کوم چې د هغوئ ګناه معاف کړه، خو کۀ تا داسې ونۀ کړل، نو بيا تۀ زما نوم د هغه کِتاب نه وران کړه چې په هغې کښې دې د خپلو خلقو نومونه ليکلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2397, 'Exodus 32:33', 'Exodus', 32, 33, '&nbsp;مالِک خُدائ موسىٰ ته وفرمائيل، ”زۀ به د خپل کِتاب نه د هغوئ نومونه وران کړم چا چې زما خِلاف ګناه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2398, 'Exodus 32:34', 'Exodus', 32, 34, '&nbsp;اوس لاړ شه، خلق هغه ځائ ته بوځه کوم چې ما درته ښودلے دے. او ګوره، زما فرښته به ستا لارښودنه کوى، خو هغه وخت راروان دے چې زۀ به دې خلقو له د هغوئ د ګناه سزا ورکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2399, 'Exodus 32:35', 'Exodus', 32, 35, '&nbsp;نو مالِک خُدائ په هغه خلقو يو وبا راولېږله، ځکه چې د هغوئ په وجه هارون د سرو زرو سخے جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(2400, 'Exodus 33:1', 'Exodus', 33, 1, '&nbsp;بيا مالِک خُدائ موسىٰ ته وفرمائيل، ”تۀ او دا خلق چې تا د مِصر د مُلک نه راوويستل، د دې ځائ نه لاړ شئ او هغه زمکې ته لاړ شئ د کومې چې ما اِبراهيم، اِسحاق او يعقوب او د هغوئ اولاد له د ورکولو لوظ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');